test("backfill within the window is recorded and flagged as a guess", () => {
	const { store: s, cleanup } = tmpStore();
	const prev = process.env.CRAFT_METRICS_BACKFILL_MS;
	process.env.CRAFT_METRICS_BACKFILL_MS = "120000";
