		assert.equal(got.phases.find((p) => p.name === "unattributed")!.cost_usd, 0.9);
	} finally {
		if (prev === undefined) delete process.env.CRAFT_METRICS_BACKFILL_MS;
		else process.env.CRAFT_METRICS_BACKFILL_MS = prev;
		cleanup();
	}
});

